import {World} from './world.js';
import {Renderer,mesh} from './renderer.js';
import {validateBox} from './anvil.js';
// Original File objects remain read-only and are never stored or modified.
export function createMapLibrary({modal,onCopy,toast}){
 const sources=[];let source=null,preview=null,renderer=null,generation=0,activeWorker=null,activeCancel=null;
 const $=s=>document.querySelector(s);
 const invalidate=()=>{generation++;preview=null;if($('#map-copy'))$('#map-copy').disabled=true;};
 function worker(data){activeCancel?.();return new Promise((resolve,reject)=>{const w=new Worker('./map-worker.js',{type:'module'});activeWorker=w;const finish=()=>{clearTimeout(timer);w.terminate();if(activeWorker===w){activeWorker=null;activeCancel=null;}};const timer=setTimeout(()=>{finish();reject(Error('Leitura cancelada após 30 segundos. Reduza a seleção.'));},30000);activeCancel=()=>{finish();reject(Error('Leitura cancelada.'));};w.onmessage=({data})=>{finish();data.error?reject(Error(data.error)):resolve(data.result);};w.onerror=()=>{finish();reject(Error('Falha no leitor de mapas.'));};w.postMessage(data);});}
 function cleanup(){invalidate();renderer?.dispose();renderer=null;activeCancel?.();activeCancel=null;activeWorker=null;}
 function box(){return Object.fromEntries(['minX','maxX','minY','maxY','minZ','maxZ'].map(k=>{const value=$('#map-'+k).value;if(!value.trim())throw Error('Preencha os seis limites da seleção.');return [k,Number(value)];}));}
 function setBox(b){for(const [k,v]of Object.entries(b))$('#map-'+k).value=v;invalidate();activeCancel?.();if($('#map-read'))$('#map-read').disabled=false;sizeReport();}
 function sizeReport(){try{const {w,h,d}=validateBox(box());$('#map-size').textContent=`${w} × ${h} × ${d} · ${(w*h*d).toLocaleString('pt-BR')} posições`;}catch(e){$('#map-size').textContent=e.message;}}
 function report(message,error=false){if(!$('#map-report'))return;$('#map-report').textContent=message;$('#map-report').classList.toggle('error',error);}
 async function indexSelected(){
  invalidate();const stamp=generation,file=source.files.find(f=>f.name===$('#map-region').value);report('Lendo índice e altura sugerida…');$('#map-read').disabled=true;
  try{const {chunks,suggested}=await worker({action:'index',file});if(stamp!==generation||!$('#map-chunk'))return;$('#map-chunk').replaceChildren();for(const chunk of chunks){const o=document.createElement('option');o.value=`${chunk.x},${chunk.z}`;o.textContent=`Chunk ${chunk.x}, ${chunk.z} · X ${chunk.x*16} · Z ${chunk.z*16}`;$('#map-chunk').append(o);}if(!chunks.length)throw Error('Região sem chunks gerados.');source.suggested=suggested;chooseChunk();report(`${chunks.length} chunks nesta região. Escolha o chunk e ajuste os dois cantos da área.`);$('#map-read').disabled=false;}catch(e){if(stamp===generation){report(e.message,true);if($('#map-read'))$('#map-read').disabled=false;}}
 }
 function chooseChunk(){const [cx,cz]=$('#map-chunk').value.split(',').map(Number);if(!Number.isInteger(cx)||!Number.isInteger(cz))return;setBox({minX:cx*16,maxX:cx*16+15,minZ:cz*16,maxZ:cz*16+15,...source.suggested});}
 async function readSelection(){invalidate();const stamp=generation;$('#map-read').disabled=true;report('Lendo apenas os chunks da seleção…');try{
  const bounds=box();validateBox(bounds);const result=await worker({action:'extract',files:source.files,box:bounds,options:{allowBlockEntityLoss:$('#map-loss').checked}});
  if(stamp!==generation||!$('#map-scene'))return;mesh(World.from(result));if(!renderer)renderer=new Renderer($('#map-scene'));renderer.setWorld(World.from(result));renderer.target=[result.w/2,result.h/2,result.d/2];renderer.distance=Math.max(25,Math.max(result.w,result.h,result.d)*1.8);renderer.draw();preview=result;
  report(`${result.solid.toLocaleString('pt-BR')} blocos sólidos. ${result.droppedBlockEntities} blocos com dados especiais ignorados. Mobs e biomas não são copiados. Confira a área antes de copiar.`);$('#map-copy').disabled=false;
 }catch(e){if(stamp===generation)report(e.message,true);}finally{if(stamp===generation&&$('#map-read'))$('#map-read').disabled=false;}}
 function show(){
  cleanup();modal('Copiar estruturas de outro mapa',`<p>Abra uma pasta de mundo Java descompactada ou arquivos de região <code>.mca</code>. A leitura acontece neste navegador. O mapa original não é alterado.</p><div class="dialog-actions"><button id="map-folder" class="button secondary">＋ Abrir pasta de mapa</button><button id="map-files" class="button secondary">＋ Abrir arquivos .mca</button></div><label class="map-field">Mapas nesta sessão<select id="map-source"></select></label><div id="map-controls" hidden><div class="two-cols"><label class="map-field">Arquivo de região<select id="map-region"></select></label><label class="map-field">Chunk inicial<select id="map-chunk"></select></label></div><h3>Seleção por coordenadas do mapa original</h3><p>Limites inclusivos. Ajuste os dois cantos para abranger a construção inteira, inclusive se atravessar chunks. Use as coordenadas do jogo como referência.</p><div class="three-cols">${['X','Y','Z'].map(axis=>`<label class="map-field">${axis} mínimo<input type="number" step="1" id="map-min${axis}" value="0"></label>`).join('')}</div><div class="three-cols">${['X','Y','Z'].map(axis=>`<label class="map-field">${axis} máximo<input type="number" step="1" id="map-max${axis}" value="15"></label>`).join('')}</div><p id="map-size"></p><label class="map-check"><input type="checkbox" id="map-loss"> Permitir copiar somente os blocos, sem inventários, textos de placas e outros dados especiais.</label><button id="map-read" class="button secondary">◈ Visualizar seleção</button><div class="map-viewport"><canvas id="map-scene" aria-label="Prévia 3D da seleção do mapa original"></canvas><span>Arraste para orbitar · roda para zoom</span></div><p id="map-report" role="status"></p><label class="map-field">Nome da estrutura<input id="map-name" maxlength="100" value="Estrutura copiada"></label><button id="map-copy" class="button primary" disabled>Copiar para minha biblioteca</button></div><p class="field-help">Java 1.18–1.21.11, chunks modernos, gzip/zlib/sem compressão. Descompacte ZIP antes de abrir. Bedrock, LZ4 e chunks externos .mcc não são suportados. Até 2.097.152 posições por seleção; ela ainda precisa caber no andar de destino. Biomas e entidades móveis não são transferidos. Para reabrir o mapa em outra sessão, selecione a pasta novamente.</p><input id="map-folder-input" type="file" webkitdirectory multiple hidden><input id="map-files-input" type="file" accept=".mca" multiple hidden>`);
  $('#dialog').classList.add('map-dialog');
  $('#map-folder').onclick=()=>$('#map-folder-input').click();$('#map-files').onclick=()=>$('#map-files-input').click();
  for(const id of ['map-folder-input','map-files-input'])$('#'+id).onchange=async e=>{try{addSources([...e.target.files]);fillSources();await activateSource();}catch(err){toast(err.message);}e.target.value='';};
  $('#map-source').onchange=()=>{source=sources.find(s=>s.id===$('#map-source').value);activateSource();};$('#map-region').onchange=indexSelected;$('#map-chunk').onchange=chooseChunk;
  for(const k of ['minX','maxX','minY','maxY','minZ','maxZ'])$('#map-'+k).oninput=()=>{invalidate();activeCancel?.();$('#map-read').disabled=false;sizeReport();report('Seleção alterada. Clique em Visualizar seleção antes de copiar.');};$('#map-loss').onchange=()=>{invalidate();activeCancel?.();$('#map-read').disabled=false;report('Opção alterada. Calcule uma nova prévia.');};
  $('#map-read').onclick=readSelection;
  $('#map-copy').onclick=async()=>{if(!preview)return;const asset={...preview,name:$('#map-name').value.trim()||'Estrutura copiada',sourceName:source.name};$('#map-copy').disabled=true;try{await onCopy(asset);cleanup();$('#dialog').close();toast('Estrutura salva. Ajuste a posição e clique em Aplicar construção.');}catch(e){report(e.message,true);$('#map-copy').disabled=false;}};
  fillSources();if(source)activateSource();
 }
 function addSources(files){
  const groups=new Map();for(const f of files){if(!/^r\.-?\d+\.-?\d+\.mca$/i.test(f.name))continue;const path=(f.webkitRelativePath||f.name).replaceAll('\\','/');if(/(^|\/)(entities|poi)\//.test(path))continue;const dir=path.includes('/')?path.slice(0,path.lastIndexOf('/')):'Arquivos de região';if(!groups.has(dir))groups.set(dir,[]);groups.get(dir).push(f);}
  if(!groups.size)throw Error('Nenhuma região .mca encontrada. Abra a pasta do mundo Java descompactada ou a pasta region.');
  if(groups.size>32)throw Error('Muitas dimensões. Selecione uma pasta region.');
  for(const [name,regions]of groups){if(regions.length>4096)throw Error('Máximo de 4.096 arquivos por dimensão.');if(new Set(regions.map(f=>f.name)).size!==regions.length)throw Error('Regiões duplicadas: abra uma dimensão por vez.');const entry={id:crypto.randomUUID(),name,files:regions.sort((a,b)=>a.name.localeCompare(b.name))};sources.push(entry);source=entry;}
 }
 function fillSources(){const select=$('#map-source');select.replaceChildren();for(const s of sources){const o=document.createElement('option');o.value=s.id;o.textContent=`${s.name} · ${s.files.length} regiões`;select.append(o);}if(source)select.value=source.id;}
 async function activateSource(){if(!source)return;invalidate();$('#map-controls').hidden=false;const select=$('#map-region');select.replaceChildren();for(const file of source.files){const o=document.createElement('option');o.value=file.name;o.textContent=file.name;select.append(o);}await indexSelected();}
 $('#dialog').addEventListener('close',()=>{cleanup();$('#dialog').classList.remove('map-dialog');});
 return {show};
}
